00106 static int32_t create_context(CodecContext *cp, const char *json_configuration, CodecError *error) {
00107     if(error)
00108         *error = 0;
00109 
00110     Context* context = new Context();
00111     context->configuration_ = json_configuration;
00112     context->state_ = StatePushing;
00113     context->m_iPOCLastDisplay = -MAX_INT;
00114     *cp = (void *)context;
00115 
00116     return 1;
00117 }
00118 
00119 // Push encoded data into decoder
00120 //
00121 static int32_t push_packet(CodecContext c, const uint8_t *data, size_t length, CodecMetadata metadata, int8_t eos, CodecError *error) {
00122     Context *context = (Context *)c;
00123     if(error)
00124         *error = 0;
00125 
00126     switch(context->state_) {
00127     case StatePushing:
00128         if(!eos) {
00129             CHECK(data);
00130             CHECK(length >= 3);
00131             // Fixup NALU start code - if first is 3 bytes, make it 4
00132             if (data[0] == '\0' && data[1] == '\0' && data[2] == '\1') {
00133                 char const zero = '\0';
00134                 context->base_bitstream_.put(0);
00135             }
00136 
00137             // Accumulate AUs into a temporary buffer
00138             context->base_bitstream_.write((const char *)data, length);
00139         } else {
00141             context->state_ = StateDecoding;
00142         }
00143         return 0;
00144 
00145     default:
00146         ERR("Unexpected decoder state");
00147     }
00148     return 0;
00149 }
00150 
00151 static int32_t pull_image(CodecContext c, CodecImage* image, CodecMetadata *metadata, int8_t* eos, CodecError *error){
00152     Context *context = (Context *)c;
00153     if(error)
00154         *error = 0;
00155 
00156     switch(context->state_) {
00157     case StatePushing:
00158         // Still accumulating input stream
00159         *eos = 0;
00160         return 0;
00161 
00162     case StateDecoding:
00163         context->m_cTDecTop.create();
00164         context->m_cTDecTop.init();
00165 
00166         context->decoder_thread_ = std::thread([context] {
00167                 context->flush();
00168                 context->decoded_images_.push(nullptr);
00169             });
00170 
00171         context->state_ = StateFlushing;
00172         /* Fall through */
00173 
00174     case StateFlushing:
00175         context->decoded_images_.pop(context->decoded_image_);
00176         if(context->decoded_image_) {
00177             *image = context->decoded_image_->image_;
00178             *eos = 0;
00179             return 1;
00180         } else {
00181             if(context->decoder_thread_.joinable())
00182                 context->decoder_thread_.join();
00183             *eos = 1;
00184             return 0;
00185         }
00186     default:
00187         ERR("Unexpected decoder state");
00188     }
00189     return 0;
00190 }
