00193 void Context::flush() {
00194     Bool openedRecon = false;
00195     bool loopFiltered = false;
00196     int poc = 0;
00197     TComList<TComPic *> *pcListPic = NULL;
00198     InputByteStream bytestream(base_bitstream_);
00199 
00200     while (!!base_bitstream_) {
00201         streampos location = base_bitstream_.tellg();
00202 
00203         AnnexBStats stats = AnnexBStats();
00204         InputNALUnit nalu;
00205         byteStreamNALUnit(bytestream, nalu.getBitstream().getFifo(), stats);
00206 
00207         // call actual decoding function
00208         Bool bNewPicture = false;
00209         if (nalu.getBitstream().getFifo().empty()) {
00210             WARN("Attempt to decode an empty NAL unit");
00211         } else {
00212             read(nalu);
00213             int skip = 0;
00214             bNewPicture = m_cTDecTop.decode(nalu, skip, m_iPOCLastDisplay);
00215 
00216             if (bNewPicture) {
00217                 base_bitstream_.clear();
00218                 base_bitstream_.seekg(location - streamoff(3));
00219                 bytestream.reset();
00220             }
00221         }
00222 
00223         if ((bNewPicture || !base_bitstream_ || nalu.m_nalUnitType == NAL_UNIT_EOS) && !m_cTDecTop.getFirstSliceInSequence()) {
00224             if (!loopFiltered || base_bitstream_) {
00225                 m_cTDecTop.executeLoopFilters(poc, pcListPic);
00226             }
00227             loopFiltered = (nalu.m_nalUnitType == NAL_UNIT_EOS);
00228             if (nalu.m_nalUnitType == NAL_UNIT_EOS) {
00229                 m_cTDecTop.setFirstSliceInSequence(true);
00230             }
00231         } else if ((bNewPicture || !base_bitstream_ || nalu.m_nalUnitType == NAL_UNIT_EOS) &&
00232                    m_cTDecTop.getFirstSliceInSequence()) {
00233             m_cTDecTop.setFirstSliceInPicture(true);
00234         }
00235 
00236         if (pcListPic) {
00237             if (!openedRecon) {
00238                 const BitDepths &bitDepths =
00239                     pcListPic->front()->getPicSym()->getSPS().getBitDepths(); // use bit depths of first reconstructed picture.
00240                 for (UInt channelType = 0; channelType < MAX_NUM_CHANNEL_TYPE; channelType++) {
00241                     if (m_outputBitDepth[channelType] == 0) {
00242                         m_outputBitDepth[channelType] = bitDepths.recon[channelType];
00243                     }
00244                 }
00245 
00246                 m_cTVideoIOYuvRecon.open(this, m_outputBitDepth, m_outputBitDepth, bitDepths.recon); // write mode
00247                 openedRecon = true;
00248             }
00249 
00250             // write reconstruction to file
00251             if (bNewPicture) {
00252                 WriteOutput(pcListPic, nalu.m_temporalId);
00253             }
00254             if ((bNewPicture || nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_CRA) && m_cTDecTop.getNoOutputPriorPicsFlag()) {
00255                 m_cTDecTop.checkNoOutputPriorPics(pcListPic);
00256                 m_cTDecTop.setNoOutputPriorPicsFlag(false);
00257             }
00258             if (bNewPicture &&
00259                 (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL || nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP ||
00260                  nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_BLA_N_LP || nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_BLA_W_RADL ||
00261                  nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_BLA_W_LP)) {
00262                 FlushOutput(pcListPic);
00263             }
00264             if (nalu.m_nalUnitType == NAL_UNIT_EOS) {
00265                 WriteOutput(pcListPic, nalu.m_temporalId);
00266                 m_cTDecTop.setFirstSliceInPicture(false);
00267             }
00268             // write reconstruction to file -- for additional bumping as defined in C.5.2.3
00269             if (!bNewPicture && nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_TRAIL_N &&
00270                 nalu.m_nalUnitType <= NAL_UNIT_RESERVED_VCL31) {
00271                 WriteOutput(pcListPic, nalu.m_temporalId);
00272             }
00273         }
00274     }
00275 
00276     FlushOutput(pcListPic);
00277 
00278     // delete buffers
00279     m_cTDecTop.deletePicBuffer();
00280 }
