00285 void Context::WriteOutput(TComList<TComPic *> *pcListPic, unsigned int tId) {
00286     if (pcListPic->empty()) {
00287         return;
00288     }
00289 
00290     TComList<TComPic *>::iterator iterPic = pcListPic->begin();
00291     Int numPicsNotYetDisplayed = 0;
00292     Int dpbFullness = 0;
00293     const TComSPS *activeSPS = &(pcListPic->front()->getPicSym()->getSPS());
00294     UInt numReorderPicsHighestTid;
00295     UInt maxDecPicBufferingHighestTid;
00296     UInt maxNrSublayers = activeSPS->getMaxTLayers();
00297 
00298     numReorderPicsHighestTid = activeSPS->getNumReorderPics(maxNrSublayers - 1);
00299     maxDecPicBufferingHighestTid = activeSPS->getMaxDecPicBuffering(maxNrSublayers - 1);
00300 
00301     while (iterPic != pcListPic->end()) {
00302         TComPic *pcPic = *(iterPic);
00303         if (pcPic->getOutputMark() && pcPic->getPOC() > m_iPOCLastDisplay) {
00304             numPicsNotYetDisplayed++;
00305             dpbFullness++;
00306         } else if (pcPic->getSlice(0)->isReferenced()) {
00307             dpbFullness++;
00308         }
00309         iterPic++;
00310     }
00311 
00312     iterPic = pcListPic->begin();
00313 
00314     if (numPicsNotYetDisplayed > 2) {
00315         iterPic++;
00316     }
00317 
00318     TComPic *pcPic = *(iterPic);
00319     if (numPicsNotYetDisplayed > 2 && pcPic->isField()) // Field Decoding
00320     {
00321         TComList<TComPic *>::iterator endPic = pcListPic->end();
00322         endPic--;
00323         iterPic = pcListPic->begin();
00324         while (iterPic != endPic) {
00325             TComPic *pcPicTop = *(iterPic);
00326             iterPic++;
00327             TComPic *pcPicBottom = *(iterPic);
00328 
00329             if (pcPicTop->getOutputMark() && pcPicBottom->getOutputMark() &&
00330                 (numPicsNotYetDisplayed > numReorderPicsHighestTid || dpbFullness > maxDecPicBufferingHighestTid) &&
00331                 (!(pcPicTop->getPOC() % 2) && pcPicBottom->getPOC() == pcPicTop->getPOC() + 1) &&
00332                 (pcPicTop->getPOC() == m_iPOCLastDisplay + 1 || m_iPOCLastDisplay < 0)) {
00333                 // write to file
00334                 numPicsNotYetDisplayed = numPicsNotYetDisplayed - 2;
00335                 const Window &conf = pcPicTop->getConformanceWindow();
00336                 const Window defDisp = pcPicTop->getDefDisplayWindow();
00337                 const Bool isTff = pcPicTop->isTopField();
00338 
00339                 m_cTVideoIOYuvRecon.write(pcPicTop->getPicYuvRec(), pcPicBottom->getPicYuvRec(),
00340                                           IPCOLOURSPACE_UNCHANGED /*m_outputColourSpaceConvert*/,
00341                                           conf.getWindowLeftOffset() + defDisp.getWindowLeftOffset(),
00342                                           conf.getWindowRightOffset() + defDisp.getWindowRightOffset(),
00343                                           conf.getWindowTopOffset() + defDisp.getWindowTopOffset(),
00344                                           conf.getWindowBottomOffset() + defDisp.getWindowBottomOffset(), NUM_CHROMA_FORMAT, isTff);
00345 
00346                 // update POC of display order
00347                 m_iPOCLastDisplay = pcPicBottom->getPOC();
00348 
00349                 // erase non-referenced picture in the reference picture list after display
00350                 if (!pcPicTop->getSlice(0)->isReferenced() && pcPicTop->getReconMark() == true) {
00351                     pcPicTop->setReconMark(false);
00352 
00353                     // mark it should be extended later
00354                     pcPicTop->getPicYuvRec()->setBorderExtension(false);
00355                 }
00356                 if (!pcPicBottom->getSlice(0)->isReferenced() && pcPicBottom->getReconMark() == true) {
00357                     pcPicBottom->setReconMark(false);
00358 
00359                     // mark it should be extended later
00360                     pcPicBottom->getPicYuvRec()->setBorderExtension(false);
00361                 }
00362                 pcPicTop->setOutputMark(false);
00363                 pcPicBottom->setOutputMark(false);
00364             }
00365         }
00366     } else if (!pcPic->isField()) // Frame Decoding
00367     {
00368         iterPic = pcListPic->begin();
00369 
00370         while (iterPic != pcListPic->end()) {
00371             pcPic = *(iterPic);
00372 
00373             if (pcPic->getOutputMark() && pcPic->getPOC() > m_iPOCLastDisplay &&
00374                 (numPicsNotYetDisplayed > numReorderPicsHighestTid || dpbFullness > maxDecPicBufferingHighestTid)) {
00375                 // write to file
00376                 numPicsNotYetDisplayed--;
00377                 if (pcPic->getSlice(0)->isReferenced() == false) {
00378                     dpbFullness--;
00379                 }
00380 
00381                 const Window &conf = pcPic->getConformanceWindow();
00382                 const Window defDisp = true /*m_respectDefDispWindow*/ ? pcPic->getDefDisplayWindow() : Window();
00383 
00384                 m_cTVideoIOYuvRecon.write(pcPic->getPicYuvRec(), IPCOLOURSPACE_UNCHANGED /*m_outputColourSpaceConvert*/,
00385                                           conf.getWindowLeftOffset() + defDisp.getWindowLeftOffset(),
00386                                           conf.getWindowRightOffset() + defDisp.getWindowRightOffset(),
00387                                           conf.getWindowTopOffset() + defDisp.getWindowTopOffset(),
00388                                           conf.getWindowBottomOffset() + defDisp.getWindowBottomOffset(), NUM_CHROMA_FORMAT,
00389                                           false /*m_bClipOutputVideoToRec709Range */);
00390 
00391                 // update POC of display order
00392                 m_iPOCLastDisplay = pcPic->getPOC();
00393 
00394                 // erase non-referenced picture in the reference picture list after display
00395                 if (!pcPic->getSlice(0)->isReferenced() && pcPic->getReconMark() == true) {
00396                     pcPic->setReconMark(false);
00397 
00398                     // mark it should be extended later
00399                     pcPic->getPicYuvRec()->setBorderExtension(false);
00400                 }
00401                 pcPic->setOutputMark(false);
00402             }
00403 
00404             iterPic++;
00405         }
00406     }
00407 }
