00411 void Context::FlushOutput(TComList<TComPic *> *pcListPic) {
00412     if (!pcListPic || pcListPic->empty()) {
00413         return;
00414     }
00415     TComList<TComPic *>::iterator iterPic = pcListPic->begin();
00416 
00417     iterPic = pcListPic->begin();
00418     TComPic *pcPic = *(iterPic);
00419 
00420     if (pcPic->isField()) // Field Decoding
00421     {
00422         TComList<TComPic *>::iterator endPic = pcListPic->end();
00423         endPic--;
00424         TComPic *pcPicTop, *pcPicBottom = NULL;
00425         while (iterPic != endPic) {
00426             pcPicTop = *(iterPic);
00427             iterPic++;
00428             pcPicBottom = *(iterPic);
00429 
00430             if (pcPicTop->getOutputMark() && pcPicBottom->getOutputMark() && !(pcPicTop->getPOC() % 2) &&
00431                 (pcPicBottom->getPOC() == pcPicTop->getPOC() + 1)) {
00432                 // write to file
00433                 const Window &conf = pcPicTop->getConformanceWindow();
00434                 const Window defDisp = true /*m_respectDefDispWindow*/ ? pcPicTop->getDefDisplayWindow() : Window();
00435                 const Bool isTff = pcPicTop->isTopField();
00436                 m_cTVideoIOYuvRecon.write(pcPicTop->getPicYuvRec(), pcPicBottom->getPicYuvRec(),
00437                                           IPCOLOURSPACE_UNCHANGED /*m_outputColourSpaceConvert*/,
00438                                           conf.getWindowLeftOffset() + defDisp.getWindowLeftOffset(),
00439                                           conf.getWindowRightOffset() + defDisp.getWindowRightOffset(),
00440                                           conf.getWindowTopOffset() + defDisp.getWindowTopOffset(),
00441                                           conf.getWindowBottomOffset() + defDisp.getWindowBottomOffset(), NUM_CHROMA_FORMAT, isTff);
00442 
00443                 // update POC of display order
00444                 m_iPOCLastDisplay = pcPicBottom->getPOC();
00445 
00446                 // erase non-referenced picture in the reference picture list after display
00447                 if (!pcPicTop->getSlice(0)->isReferenced() && pcPicTop->getReconMark() == true) {
00448                     pcPicTop->setReconMark(false);
00449 
00450                     // mark it should be extended later
00451                     pcPicTop->getPicYuvRec()->setBorderExtension(false);
00452                 }
00453                 if (!pcPicBottom->getSlice(0)->isReferenced() && pcPicBottom->getReconMark() == true) {
00454                     pcPicBottom->setReconMark(false);
00455 
00456                     // mark it should be extended later
00457                     pcPicBottom->getPicYuvRec()->setBorderExtension(false);
00458                 }
00459                 pcPicTop->setOutputMark(false);
00460                 pcPicBottom->setOutputMark(false);
00461 
00462                 if (pcPicTop) {
00463                     pcPicTop->destroy();
00464                     delete pcPicTop;
00465                     pcPicTop = NULL;
00466                 }
00467             }
00468         }
00469         if (pcPicBottom) {
00470             pcPicBottom->destroy();
00471             delete pcPicBottom;
00472             pcPicBottom = NULL;
00473         }
00474     } else // Frame decoding
00475     {
00476         while (iterPic != pcListPic->end()) {
00477             pcPic = *(iterPic);
00478 
00479             if (pcPic->getOutputMark()) {
00480                 // write to file
00481                 const Window &conf = pcPic->getConformanceWindow();
00482                 const Window defDisp = true /*m_respectDefDispWindow*/ ? pcPic->getDefDisplayWindow() : Window();
00483 
00484                 m_cTVideoIOYuvRecon.write(pcPic->getPicYuvRec(), IPCOLOURSPACE_UNCHANGED /*m_outputColourSpaceConvert*/,
00485                                           conf.getWindowLeftOffset() + defDisp.getWindowLeftOffset(),
00486                                           conf.getWindowRightOffset() + defDisp.getWindowRightOffset(),
00487                                           conf.getWindowTopOffset() + defDisp.getWindowTopOffset(),
00488                                           conf.getWindowBottomOffset() + defDisp.getWindowBottomOffset(), NUM_CHROMA_FORMAT,
00489                                           false /*m_bClipOutputVideoToRec709Range*/);
00490 
00491                 // update POC of display order
00492                 m_iPOCLastDisplay = pcPic->getPOC();
00493 
00494                 // erase non-referenced picture in the reference picture list after display
00495                 if (!pcPic->getSlice(0)->isReferenced() && pcPic->getReconMark() == true) {
00496                     pcPic->setReconMark(false);
00497 
00498                     // mark it should be extended later
00499                     pcPic->getPicYuvRec()->setBorderExtension(false);
00500                 }
00501                 pcPic->setOutputMark(false);
00502             }
00503             if (pcPic != NULL) {
00504                 pcPic->destroy();
00505                 delete pcPic;
00506                 pcPic = NULL;
00507             }
00508             iterPic++;
00509         }
00510     }
00511     pcListPic->clear();
00512     m_iPOCLastDisplay = -MAX_INT;
00513 }
