00515 void Context::picture_begin(bool is16bit, UInt width, UInt height, ChromaFormat format) {
00516     output_frame_++;
00517     size_t frame_size = (width * height + 2 * (width / 2 * height / 2)) * (is16bit ? 2 : 1);
00518 
00519     CHECK(!writing_image_);
00520 
00521     writing_image_ = std::shared_ptr<DecodedImage>(new DecodedImage());
00522 
00523     writing_image_->buffer_.reserve(frame_size);
00524 
00525     writing_image_->image_.bpp = is16bit ? 2 : 1;
00526     writing_image_->image_.width_y = width;
00527     writing_image_->image_.height_y = height;
00528     writing_image_->image_.stride_y = width * writing_image_->image_.bpp;
00529 
00530     writing_image_->image_.width_uv = width / 2;
00531     writing_image_->image_.height_uv = height / 2;
00532     writing_image_->image_.stride_uv = (width / 2) * writing_image_->image_.bpp;
00533 }
00534 
00535 int Context::write(const uint8_t *data, size_t size) {
00536     CHECK(writing_image_);
00537     writing_image_->buffer_.insert(writing_image_->buffer_.end(), data, data + size);
00538     return (int)size;
00539 }
00540 
00541 void Context::picture_end() {
00542 
00543     CHECK(writing_image_);
00544     writing_image_->image_.data_y = writing_image_->buffer_.data();
00545     writing_image_->image_.data_u = writing_image_->image_.data_y + writing_image_->image_.stride_y * writing_image_->image_.height_y;
00546     writing_image_->image_.data_v = writing_image_->image_.data_u + writing_image_->image_.stride_uv * writing_image_->image_.height_uv;
00547 
00548     decoded_images_.push(writing_image_);
00549     writing_image_ = nullptr;
00550 }
